/**
 * The world as a dot matrix.
 *
 * An equirectangular grid at 3-degree steps: one cell per dot, '.' water and
 * '#' land, written out so the source shows the map it draws. Generated by
 * rasterising coarse continent outlines with 3x3 supersampling — a cell counts
 * as land if any sample lands on it, which keeps thin coasts (Portugal, west
 * Greenland, Iceland) from dropping out. The same rule fills the Bay of Biscay
 * and the Baltic, each barely a cell wide at this step; losing capitals to keep
 * two small seas would have been the worse trade.
 *
 * Antarctica is omitted, as it is in most dot maps of this kind — it spans the
 * full width and reads as a rule under the map rather than as land.
 */
export const MAP_COLS = 120;
export const MAP_ROWS = 45;
/** Latitude of the grid's top edge; the bottom edge is MAP_LAT_TOP - MAP_ROWS * MAP_STEP. */
export const MAP_LAT_TOP = 78;
export const MAP_STEP = 3;

export const WORLD_ROWS: readonly string[] = [
  '......................................###############......................................###..........................',
  '........................................##############............................###################...................',
  '......#########..######.......###.......#############.............######.....######################################.....',
  '....###############################......#########..............########################################################',
  '....################################......######....####.......#########################################################',
  '....###########################..##........###...............###########################################################',
  '.....#####...################.............................##.######.################################################....',
  '...............################..#......................####..####################################################......',
  '................#######################.................##########################################################......',
  '.................########################.................#################################################....#........',
  '..................######################...................################################################.............',
  '..................####################..................##############...###.#############################.##...........',
  '..................###################...................#####...##.#########..##########################..##............',
  '...................#################....................##...###.....##################################...##............',
  '...................################......................#########.....################################.###.............',
  '....................##############.......................#############################################.#................',
  '.....................#############......................#############################################...................',
  '......................######....##.....................#############################################....................',
  '.......................#####...####...................#########################...#################.....................',
  '.........................######...##..................########################.....######..######.......................',
  '..........................#####.......................#######################.......####....####....##..................',
  '.............................####.....................######################........###.....####....##..................',
  '...............................##.######...............######################........##.....####....##..................',
  '.................................#########.............######################.........##.....##.....##..................',
  '..................................#########.............####################...............#.##.........................',
  '..................................##########..................#############................##.#.######..................',
  '.................................#############................############..................##..######.##...............',
  '.................................###############..............############...................###.####...####............',
  '.................................################..............###########.....................####.......####..........',
  '.................................###############...............###########.............................##.##............',
  '..................................##############...............##########.###........................#######............',
  '...................................############.................#########.###.......................#########...........',
  '....................................###########.................########..###.....................############..........',
  '....................................##########..................########..###....................##############.........',
  '....................................#########...................#######....#......................#############.........',
  '....................................########.....................######...........................#############.........',
  '....................................#######......................#####............................#############.........',
  '....................................#######.......................###..............................##...#######......#..',
  '...................................#######...............................................................#####.......##.',
  '...................................#####....................................................................##.......##.',
  '...................................#####....................................................................##.....###..',
  '...................................#####...........................................................................##...',
  '...................................####.................................................................................',
  '...................................###..................................................................................',
  '........................................................................................................................',
];

/** A country's extent, as [west, south, east, north]. */
export type LandBox = readonly [number, number, number, number];

export interface WorldPaths {
  /** Every land dot outside the lit country. */
  rest: string;
  /** The lit country's own dots; empty when no country is given. */
  lit: string;
}

/** One dot, as two half-arcs — cheaper to parse than four beziers. */
function dot(cx: number, cy: number, radius: number): string {
  const r = radius.toFixed(2);
  const d2 = (radius * 2).toFixed(2);
  return `M${(cx - radius).toFixed(2)} ${cy.toFixed(2)}a${r} ${r} 0 1 0 ${d2} 0a${r} ${r} 0 1 0 -${d2} 0Z`;
}

/**
 * The map as two paths, in a viewBox of MAP_COLS x MAP_ROWS units.
 *
 * Nearly two thousand `<Circle>` elements would be two thousand native views on
 * a surface that scrolls, tilts and springs. Every dot is a subpath of a single
 * `<Path>` instead — two here, so the lit country can take its own fill and
 * radius without splitting into per-dot elements. Built once and memoised.
 *
 * A cell is lit when it *overlaps* the box rather than when its centre falls
 * inside: at three degrees a cell is wider than Singapore or Hong Kong, and
 * centre-testing would leave those countries unlit on their own passport.
 */
const pathCache = new Map<string, WorldPaths>();

export function worldDotsPaths(
  radius: number,
  litRadius: number,
  box?: LandBox
): WorldPaths {
  const key = `${radius}|${litRadius}|${box ? box.join(',') : ''}`;
  const cached = pathCache.get(key);
  if (cached) return cached;

  const rest: string[] = [];
  const lit: string[] = [];

  for (let row = 0; row < WORLD_ROWS.length; row++) {
    const line = WORLD_ROWS[row];
    const north = MAP_LAT_TOP - row * MAP_STEP;
    const south = north - MAP_STEP;
    for (let col = 0; col < line.length; col++) {
      if (line[col] !== '#') continue;
      const west = -180 + col * MAP_STEP;
      const east = west + MAP_STEP;
      const isLit =
        !!box && west < box[2] && east > box[0] && south < box[3] && north > box[1];
      const cx = col + 0.5;
      const cy = row + 0.5;
      if (isLit) lit.push(dot(cx, cy, litRadius));
      else rest.push(dot(cx, cy, radius));
    }
  }

  const paths: WorldPaths = { rest: rest.join(''), lit: lit.join('') };
  pathCache.set(key, paths);
  return paths;
}

/** Grid position of a coordinate, in the same units as the paths' viewBox. */
export function project(lon: number, lat: number): { x: number; y: number } {
  return {
    x: (lon + 180) / MAP_STEP,
    y: (MAP_LAT_TOP - lat) / MAP_STEP,
  };
}
